/// Rule 3: [`SessionEvent::Ended`] comes only from [`Session::on_exit`], exactly once, as its
/// last output, carrying the exit; after it every call is silent, there's no deadline, and
/// every control returns [`ControlError::Closed`].
///
/// It checks exits at every stage: right after the start, while idle, during a turn, after
/// [`Control::Close`], each with stdout closed first and (where it matters) still open, and
/// each after a tick far past every deadline, the script's stderr lines and a truncated line,
/// and (once stdout closed) another tick far past that, none of which may end the session.
/// Each exit carries a different [`ExitInfo`], which `Ended` must carry back.
pub fn check_ended_once_and_last(
    make: &mut dyn FnMut() -> Box<dyn Session>,
    script: &Script,
    now: Instant,
) {
    type Lead = fn(&mut dyn Session, &Script, Instant) -> Vec<Output>;
    let scenarios: [(&str, Lead, bool); 8] = [
        (
            "an exit with an approval pending (or during a turn, without approval lines)",
            |s, script, now| {
                let mut out = [open(s, script, now), into_turn(s, script, now)].concat();
                if let Some(approval) = &script.approval {
                    out.extend(raise(s, approval, now));
                }
                out
            },
            true,
        ),
        (
            "an exit right after the start",
            |s, _, now| s.start(now),
            true,
        ),
        (
            "an exit right after the start, stdout still open",
            |s, _, now| s.start(now),
            false,
        ),
        ("an exit while idle", open, true),
        (
            "an exit during a turn",
            |s, script, now| [open(s, script, now), into_turn(s, script, now)].concat(),
            true,
        ),
        (
            "an exit during a turn, stdout still open",
            |s, script, now| [open(s, script, now), into_turn(s, script, now)].concat(),
            false,
        ),
        (
            "an exit after the turn",
            |s, script, now| {
                [
                    open(s, script, now),
                    into_turn(s, script, now),
                    end_turn(s, script, now),
                ]
                .concat()
            },
            true,
        ),
        (
            "an exit after Close",
            |s, script, now| {
                let mut out = open(s, script, now);
                out.extend(
                    s.control(Control::Close, now)
                        .unwrap_or_else(|e| panic!("testkit: Close was refused: {e}")),
                );
                out
            },
            true,
        ),
    ];
    let late = now + Duration::from_secs(24 * 3600);
    let after_eof = late + Duration::from_secs(24 * 3600);
    for (i, (name, lead, stdout_closes_first)) in scenarios.into_iter().enumerate() {
        let exit = varied_exit(i);
        let mut session = make();
        let mut before = lead(session.as_mut(), script, now);
        // Things that happen before an exit and must not end the session themselves.
        for line in &script.stderr {
            before.extend(session.on_stderr_line(line, now));
        }
        before.extend(session.on_truncated(MAX_LINE_BYTES + 1, now));
        before.extend(session.on_tick(late));
        if stdout_closes_first {
            before.extend(session.on_stdout_closed(late));
            // A session must not end itself some time after EOF: only the exit ends it.
            before.extend(session.on_tick(after_eof));
        }
        assert!(
            !before.iter().any(is_ended),
            "rule 3 broken ({name}): Ended came before on_exit: {before:?}"
        );
        let out = session.on_exit(exit, after_eof);
        assert_eq!(
            out.iter().filter(|o| is_ended(o)).count(),
            1,
            "rule 3 broken ({name}): on_exit must emit Ended exactly once: {out:?}"
        );
        assert_eq!(
            out.last(),
            Some(&Output::Event(SessionEvent::Ended { exit })),
            "rule 3 broken ({name}): Ended, with the exit given, must be on_exit's last output"
        );
        assert_finished(session.as_mut(), script, name, after_eof);
    }
}

/// After Ended: every call is silent, no deadline, every control is refused as Closed.
fn assert_finished(session: &mut dyn Session, script: &Script, name: &str, now: Instant) {
    let later = now + Duration::from_secs(3600);
    let mut calls = vec![
        ("on_exit again", session.on_exit(varied_exit(1), later)),
        ("on_stdout_closed", session.on_stdout_closed(later)),
        ("on_truncated", session.on_truncated(10, later)),
        ("on_stderr_line", session.on_stderr_line(b"error", later)),
        ("on_tick", session.on_tick(later)),
        ("on_line (not JSON)", session.on_line(b"not json", later)),
    ];
    let lines = script
        .opening
        .iter()
        .chain(&script.turn)
        .chain(&script.turn_end);
    for line in lines {
        calls.push(("on_line (a script line)", session.on_line(line, later)));
    }
    if let Some(approval) = &script.approval {
        calls.push((
            "on_line (the approval request)",
            session.on_line(&approval.request, later),
        ));
        if let Some(cancel) = &approval.cancel {
            calls.push((
                "on_line (the approval cancel)",
                session.on_line(cancel, later),
            ));
        }
    }
    for line in &script.stderr {
        calls.push((
            "on_stderr_line (a script line)",
            session.on_stderr_line(line, later),
        ));
    }
    for (what, out) in calls {
        assert!(
            out.is_empty(),
            "rule 3 broken ({name}): {what} after Ended emitted {out:?}"
        );
    }
    assert_eq!(
        session.next_deadline(),
        None,
        "rule 3 broken ({name}): a deadline after Ended"
    );
    for control in [
        send(false),
        send(true),
        Control::Interrupt,
        Control::Close,
        answer_never_raised(),
    ] {
        assert_eq!(
            session.control(control.clone(), later),
            Err(ControlError::Closed),
            "rule 3 broken ({name}): {control:?} after Ended must return Closed"
        );
    }
}

const EXIT: ExitInfo = ExitInfo {
    code: Some(0),
    signal: None,
};

/// A different exit per scenario, so a session can't pass by always reporting the same one.
fn varied_exit(i: usize) -> ExitInfo {
    match i % 4 {
        0 => EXIT,
        1 => ExitInfo {
            code: Some(3),
            signal: None,
        },
        2 => ExitInfo {
            code: None,
            signal: Some(15),
        },
        _ => ExitInfo {
            code: None,
            signal: None,
        },
    }
}

fn send(urgent: bool) -> Control {
    Control::Send {
        text: "org-runtime testkit".to_owned(),
        urgent,
    }
}

fn answer(id: &ApprovalId) -> Control {
    Control::Answer {
        request_id: id.clone(),
        decision: Decision::AllowOnce,
    }
}

/// Feeds the approval request; the session must raise it with the script's id.
fn raise(session: &mut dyn Session, approval: &ScriptApproval, now: Instant) -> Vec<Output> {
    let out = session.on_line(&approval.request, now);
    check_writes(&out, "the approval request");
    let request = out.iter().find_map(|o| match o {
        Output::Event(SessionEvent::ApprovalRequested(request)) if request.id == approval.id => {
            Some(request)
        }
        _ => None,
    });
    let Some(request) = request else {
        panic!(
            "testkit: the script's approval line didn't raise approval {:?}: {out:?}",
            approval.id
        )
    };
    assert_eq!(
        request.escalation,
        request.effective_escalation(),
        "escalation rule broken: a {:?} request must not carry {:?}",
        request.kind,
        request.escalation
    );
    out
}

fn answer_never_raised() -> Control {
    Control::Answer {
        request_id: ApprovalId::new("org-runtime-testkit-never-raised"),
        decision: Decision::AllowOnce,
    }
}

fn is_ended(output: &Output) -> bool {
    matches!(output, Output::Event(SessionEvent::Ended { .. }))
}

/// Starts the session and feeds the opening; it must emit Ready.
fn open(session: &mut dyn Session, script: &Script, now: Instant) -> Vec<Output> {
    let mut out = session.start(now);
    for line in &script.opening {
        out.extend(session.on_line(line, now));
    }
    check_writes(&out, "the opening");
    assert!(
        out.iter()
            .any(|o| matches!(o, Output::Event(SessionEvent::Ready { .. }))),
        "testkit: the script's opening lines didn't make the session Ready: {out:?}"
    );
    out
}

/// Sends a normal message while idle and feeds the turn lines.
fn into_turn(session: &mut dyn Session, script: &Script, now: Instant) -> Vec<Output> {
    let mut out = session
        .control(send(false), now)
        .unwrap_or_else(|e| panic!("testkit: a normal Send while idle was refused: {e}"));
    for line in &script.turn {
        out.extend(session.on_line(line, now));
    }
    check_writes(&out, "a Send");
    out
}

fn end_turn(session: &mut dyn Session, script: &Script, now: Instant) -> Vec<Output> {
    let mut out = Vec::new();
    for line in &script.turn_end {
        out.extend(session.on_line(line, now));
    }
    check_writes(&out, "the end of a turn");
    out
}

/// A control applied to one session of a [`Pair`].
type ControlStep<'a> = dyn Fn(&mut dyn Session) -> Result<Vec<Output>, ControlError> + 'a;

/// Two sessions in lockstep, for rule 2.
struct Pair {
    a: Box<dyn Session>,
    b: Box<dyn Session>,
    now: Instant,
}

impl Pair {
    /// The same step on both; they must answer alike.
    fn both(&mut self, what: &str, step: &dyn Fn(&mut dyn Session) -> Vec<Output>) {
        let a = step(self.a.as_mut());
        let b = step(self.b.as_mut());
        assert_eq!(
            a, b,
            "rule 2 broken: after a refused control, the session answered {what} differently"
        );
        self.same_deadline(what);
    }

    /// The same control on both; their results (success or error) must be alike.
    fn both_result(&mut self, what: &str, step: &ControlStep) {
        let a = step(self.a.as_mut());
        let b = step(self.b.as_mut());
        assert_eq!(
            a, b,
            "rule 2 broken: after a refused control, the session answered {what} differently"
        );
        self.same_deadline(what);
    }

    /// `control` on `a` alone if it fails there (the point of the check); if it succeeds, on
    /// `b` too, so they stay twins. `must_fail`: succeeding is itself a bug.
    fn try_on_a(&mut self, what: &str, control: Control, must_fail: bool) {
        match self.a.control(control.clone(), self.now) {
            Err(_) => self.same_deadline(what),
            Ok(out) => {
                let twin = self.b.control(control, self.now);
                // If the twin (which never saw the earlier refused controls) refuses it, an
                // earlier refusal changed `a`: that's rule 2, not a script problem.
                assert!(
                    !(must_fail && twin.is_err()),
                    "rule 2 broken: {what} was accepted after earlier refused controls, but \
                     refused by the twin that never saw them"
                );
                assert!(
                    !must_fail,
                    "testkit: {what} must be refused, but was accepted: {out:?}"
                );
                assert_eq!(
                    Ok(out),
                    twin,
                    "rule 2 broken (or the session isn't deterministic): {what} was handled \
                     differently by the twin that never saw the earlier refused controls"
                );
                self.same_deadline(what);
            }
        }
    }

    fn same_deadline(&self, what: &str) {
        assert_eq!(
            self.a.next_deadline(),
            self.b.next_deadline(),
            "rule 2 broken: the deadline differs after {what}"
        );
    }
}
use std::collections::BTreeMap;
use std::ffi::{OsStr, OsString};
use std::io;
use std::path::{Path, PathBuf};

use crate::invalid;

/// A captured search path with the verified release's helpers first. No ambient lookup.
#[derive(Debug)]
pub struct SearchPath(OsString);

impl SearchPath {
    /// Drop empty/relative, unavailable, and forbidden-root entries from the captured path.
    /// Roots must include the workspace and private home, resolved to their actual paths.
    /// The pinned helper directory must be absolute, existing and outside those roots.
    pub fn new(pinned_helpers: &Path, captured: &OsStr, forbidden: &[PathBuf]) -> io::Result<Self> {
        let roots = forbidden
            .iter()
            .map(|p| p.canonicalize())
            .collect::<io::Result<Vec<_>>>()?;
        if !pinned_helpers.is_absolute() {
            return Err(invalid("the pinned helper directory must be absolute"));
        }
        let pinned = pinned_helpers.canonicalize()?;
        if !pinned.is_dir() || roots.iter().any(|root| pinned.starts_with(root)) {
            return Err(invalid(
                "the helper directory overlaps a forbidden PATH root",
            ));
        }
        let mut paths = vec![pinned];
        for entry in std::env::split_paths(captured) {
            if !entry.is_absolute() {
                continue;
            }
            if let Ok(real) = entry.canonicalize() {
                if real.is_dir()
                    && !roots.iter().any(|root| real.starts_with(root))
                    && !paths.contains(&real)
                {
                    paths.push(real);
                }
            }
        }
        std::env::join_paths(paths)
            .map(Self)
            .map_err(|_| invalid("invalid search path"))
    }
}

/// An explicit environment. Debug never reveals values (which may hold run credentials).
pub struct Environment(pub(crate) BTreeMap<OsString, OsString>);

impl std::fmt::Debug for Environment {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("Environment")
            .field("names", &self.0.keys())
            .finish()
    }
}

impl Environment {
    /// Build from captured login/service data only. No server environment is inherited.
    /// Only HOME, LANG, USER, LOGNAME, SHELL, TERM and TMPDIR are accepted here.
    pub fn new(path: SearchPath, captured: &[(OsString, OsString)]) -> io::Result<Self> {
        let mut result = Self(BTreeMap::new());
        result.0.insert("PATH".into(), path.0);
        for (name, value) in captured {
            if !matches!(
                name.to_str(),
                Some("HOME" | "LANG" | "USER" | "LOGNAME" | "SHELL" | "TERM" | "TMPDIR")
            ) {
                return Err(invalid("name is not in the captured environment allowlist"));
            }
            result.insert(name.clone(), value.clone())?;
        }
        Ok(result)
    }

    /// Add caller-owned context values. This crate validates names, never their domain meaning.
    /// ORG_* identity/binding values, GH_CONFIG_DIR and the precise git config mechanism are
    /// allowed. The session mark is installed only by the recorded-spawn path.
    pub fn with_context(mut self, context: &[(OsString, OsString)]) -> io::Result<Self> {
        for (name, value) in context {
            let name_text = name
                .to_str()
                .ok_or_else(|| invalid("invalid context variable name"))?;
            let git = matches!(
                name_text,
                "GIT_CONFIG_NOSYSTEM" | "GIT_CONFIG_GLOBAL" | "GIT_CONFIG_COUNT"
            ) || indexed(name_text, "GIT_CONFIG_KEY_")
                || indexed(name_text, "GIT_CONFIG_VALUE_");
            if !is_context_name(name)
                || name_text == "ORG_SESSION_MARK"
                || (name_text.starts_with("GIT_CONFIG_") && !git)
            {
                return Err(invalid("name is not in the context environment allowlist"));
            }
            self.insert(name.clone(), value.clone())?;
        }
        Ok(self)
    }

    /// Probes reject the whole context namespace, including names that are not
    /// admitted by the more precise caller-context allowlist above.
    pub(crate) fn carries_context(&self) -> bool {
        self.0.keys().any(|name| is_context_name(name))
    }

    /// Apply the mapper-owned policy; collisions are errors even for equal values.
    pub(crate) fn with_additions(
        mut self,
        additions: &[(OsString, OsString)],
        allowed: &[&str],
    ) -> io::Result<Self> {
        for (name, value) in additions {
            if !name.to_str().is_some_and(|name| allowed.contains(&name)) {
                return Err(invalid("unreviewed runtime environment switch"));
            }
            self.insert(name.clone(), value.clone())?;
        }
        Ok(self)
    }

    pub(crate) fn insert(&mut self, name: OsString, value: OsString) -> io::Result<()> {
        use std::os::unix::ffi::OsStrExt;
        let bytes = name.as_bytes();
        if bytes.is_empty()
            || !bytes
                .iter()
                .all(|c| c.is_ascii_alphanumeric() || *c == b'_')
            || bytes[0].is_ascii_digit()
            || value.as_bytes().contains(&0)
        {
            return Err(invalid("invalid environment name or value"));
        }
        if self.0.contains_key(&name) {
            return Err(invalid("environment name collision"));
        }
        self.0.insert(name, value);
        Ok(())
    }
}

fn is_context_name(name: &OsStr) -> bool {
    let name = name.as_encoded_bytes();
    name.starts_with(b"ORG_") || name.starts_with(b"GIT_CONFIG_") || name == b"GH_CONFIG_DIR"
}

fn indexed(name: &str, prefix: &str) -> bool {
    name.strip_prefix(prefix)
        .is_some_and(|index| !index.is_empty() && index.bytes().all(|b| b.is_ascii_digit()))
}

//! Probes: short runs that check a runtime outside a session (its version, its sign-in, its
//! quota). The adapter plans them ([`crate::AgentRuntime::plan_probe`]); the supervisor runs
//! them. A probe is one of two shapes ([`ProbeRun`]):
//! - **one-shot**: write a few fixed lines, close stdin, and read the whole output with
//!   [`crate::AgentRuntime::parse_probe`] (`--version`, `auth status`);
//! - **conversation**: an exchange that needs answers read before the next line is written,
//!   driven by a sans-I/O [`ProbeSession`] (Codex's `initialize`, then `account/read`).

use std::path::PathBuf;
use std::time::Instant;

use crate::event::redact_opt;
use crate::{Line, ProbePlan, RateLimit, SpecPath};

/// What a probe needs to know: which binary to run, and where its own files are. A probe has
/// no session, so it gets none of [`crate::LaunchContext`]'s per-run values.
///
/// It's `#[non_exhaustive]` so it can grow: build one with [`ProbeContext::new`].
#[derive(Debug, Clone, PartialEq, Eq)]
#[non_exhaustive]
pub struct ProbeContext {
    /// The runtime's binary, by the real path recorded at preflight (or found on the user's
    /// `PATH` at preflight, for the first version probe).
    pub runtime_path: PathBuf,
    /// The runtime's version, if known yet, for gating flags.
    pub runtime_version: Option<String>,
    /// The agent's runtime dir, when the probe is for one agent (e.g. Antigravity's per-agent
    /// `--gemini-dir`, so a sign-in check sees the same config the sessions use). `None` for
    /// a runtime-wide probe. A real path.
    pub runtime_dir: Option<SpecPath>,
}

impl ProbeContext {
    /// A context for a runtime-wide probe of this binary, with no version known yet.
    pub fn new(runtime_path: PathBuf) -> Self {
        ProbeContext {
            runtime_path,
            runtime_version: None,
            runtime_dir: None,
        }
    }
}

/// How to run one probe.
///
/// Exhaustive on purpose, like the plan's enums: it's an instruction to the supervisor.
pub enum ProbeRun {
    /// Write [`ProbePlan::stdin_lines`], close stdin, wait for the exit (or the timeout), and
    /// give the output to [`crate::AgentRuntime::parse_probe`].
    OneShot(ProbePlan),
    /// Write [`ProbePlan::stdin_lines`], then drive `session`: feed it each stdout line and
    /// its ticks, write what it returns, and stop as soon as it returns
    /// [`ProbeStep::Done`]. Stdin stays open until then.
    Conversation {
        /// The process.
        plan: ProbePlan,
        /// The exchange.
        session: Box<dyn ProbeSession>,
    },
}

impl std::fmt::Debug for ProbeRun {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            ProbeRun::OneShot(plan) => f.debug_tuple("OneShot").field(plan).finish(),
            ProbeRun::Conversation { plan, .. } => f
                .debug_struct("Conversation")
                .field("plan", plan)
                .finish_non_exhaustive(),
        }
    }
}

/// A probe's exchange as a pure state machine, like [`crate::Session`] but for one short
/// run: no I/O, no clock, time as an input.
///
/// The supervisor writes the plan's [`ProbePlan::stdin_lines`] first, then calls
/// [`start`](Self::start), then [`on_line`](Self::on_line) for each stdout line (split by a
/// [`crate::LineFramer`]; an over-long line is dropped, not passed), [`on_tick`](Self::on_tick)
/// at [`next_deadline`](Self::next_deadline), and [`on_stdout_closed`](Self::on_stdout_closed)
/// if stdout ends first. It applies the [`ProbeStep`]s in order. Stderr isn't passed: it's
/// kept with the probe's output for the logs.
///
/// **A probe that finished never ends as a timeout.** The first [`ProbeStep::Done`] is the
/// result: the supervisor then closes stdin and stops the process, and nothing that happens
/// after (an exit code, the plan's overall timeout) changes it. The plan's timeout produces
/// a timed-out result only if no `Done` came first: the supervisor then reports
/// [`ProbeResult::Unavailable`] with [`Unavailable::Other`] ("timed out").
pub trait ProbeSession: Send {
    /// The process started.
    fn start(&mut self, now: Instant) -> Vec<ProbeStep>;
    /// One stdout line, without its `\n`.
    fn on_line(&mut self, line: &[u8], now: Instant) -> Vec<ProbeStep>;
    /// Time passed: the session's own protocol deadlines.
    fn on_tick(&mut self, now: Instant) -> Vec<ProbeStep>;
    /// Stdout ended before `Done`: the session concludes with what it has.
    fn on_stdout_closed(&mut self, now: Instant) -> ProbeResult;
    /// When the session next needs [`on_tick`](Self::on_tick), if ever.
    fn next_deadline(&self) -> Option<Instant>;
}

/// Something the supervisor does for a [`ProbeSession`], in order.
///
/// Exhaustive on purpose: it's an instruction to the supervisor.
#[derive(Debug, Clone, PartialEq)]
pub enum ProbeStep {
    /// Write this line to stdin.
    Write(Line),
    /// The probe's result. The exchange is over.
    Done(ProbeResult),
}

/// What to check.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
#[non_exhaustive]
pub enum Probe {
    /// The runtime's version, at preflight.
    Version,
    /// Whether the runtime is signed in, at preflight.
    Auth,
    /// The account's quota, for a runtime that doesn't report it in-stream (polled).
    Quota,
}

/// What a one-shot probe process produced. Output past the supervisor's cap is cut off.
///
/// It's `#[non_exhaustive]` so it can grow: build one with [`ProbeOutput::new`].
#[derive(Debug, Clone, PartialEq, Eq)]
#[non_exhaustive]
pub struct ProbeOutput {
    /// Everything it wrote to stdout.
    pub stdout: Vec<u8>,
    /// Everything it wrote to stderr.
    pub stderr: Vec<u8>,
    /// Its exit code, or `None` if a signal ended it.
    pub exit_code: Option<i32>,
    /// Whether the timeout ([`crate::ProbePlan::timeout_ms`]) stopped it **before it
    /// exited**. A probe that exited in time is never timed out, however long reading its
    /// output took.
    pub timed_out: bool,
}

impl ProbeOutput {
    /// A probe that exited (in time) with this output and exit code.
    pub fn new(stdout: Vec<u8>, stderr: Vec<u8>, exit_code: Option<i32>) -> Self {
        ProbeOutput {
            stdout,
            stderr,
            exit_code,
            timed_out: false,
        }
    }
}

/// What a probe found.
#[derive(Debug, Clone, PartialEq)]
#[non_exhaustive]
pub enum ProbeResult {
    /// The runtime's version.
    Version {
        /// As the runtime printed it, trimmed.
        raw: String,
        /// Whether it's within [`crate::Capabilities::tested_versions`], or `None` if the
        /// adapter can't tell.
        in_tested_range: Option<bool>,
    },
    /// The runtime's sign-in.
    Auth {
        /// Whether it's signed in.
        signed_in: bool,
        /// How, in the runtime's words (e.g. a subscription or an API key), where it says.
        method: Option<String>,
    },
    /// The account's rate-limit windows.
    Quota {
        /// One per window the runtime reported.
        limits: Vec<RateLimit>,
    },
    /// The probe shows the runtime can't be used.
    Unavailable {
        /// Why.
        reason: Unavailable,
    },
}

impl ProbeResult {
    /// Runs `f` over every free-text string in the result (versions, methods, details, rate
    /// limit names and times), like [`crate::SessionEvent::redact`], before the office stores
    /// or shows it: probe output is runtime text.
    pub fn redact(&mut self, f: &mut dyn FnMut(&mut String)) {
        match self {
            ProbeResult::Version {
                raw,
                in_tested_range: _,
            } => f(raw),
            ProbeResult::Auth {
                signed_in: _,
                method,
            } => redact_opt(method, f),
            ProbeResult::Quota { limits } => {
                for limit in limits {
                    limit.redact(f);
                }
            }
            ProbeResult::Unavailable { reason } => match reason {
                Unavailable::Other { detail } => f(detail),
                Unavailable::NotInstalled
                | Unavailable::SignedOut
                | Unavailable::Version
                | Unavailable::Quota => {}
            },
        }
    }
}

/// Why a runtime can't be used.
#[derive(Debug, Clone, PartialEq, Eq, Hash)]
#[non_exhaustive]
pub enum Unavailable {
    /// The binary isn't there or won't run.
    NotInstalled,
    /// It isn't signed in.
    SignedOut,
    /// Its version can't be used (unreadable, or too old for this adapter).
    Version,
    /// Its quota is used up.
    Quota,
    /// Anything else (including a probe that timed out).
    Other {
        /// What happened. Never a secret: adapters don't quote raw probe output here.
        detail: String,
    },
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::{LimitStatus, Window};

    #[test]
    fn probe_result_redact_visits_every_string() {
        let mut limit = RateLimit::new(
            Window::Other {
                id: "s:window".into(),
                mins: None,
            },
            LimitStatus::Ok,
        );
        limit.resets_at = Some("s:resets".into());
        let mut results = vec![
            ProbeResult::Version {
                raw: "s:raw".into(),
                in_tested_range: Some(true),
            },
            ProbeResult::Auth {
                signed_in: true,
                method: Some("s:method".into()),
            },
            ProbeResult::Quota {
                limits: vec![limit],
            },
            ProbeResult::Unavailable {
                reason: Unavailable::Other {
                    detail: "s:detail".into(),
                },
            },
        ];
        let mut seen = Vec::new();
        for result in &mut results {
            result.redact(&mut |s| {
                seen.push(s.clone());
                *s = "R".into();
            });
        }
        assert_eq!(
            seen,
            ["s:raw", "s:method", "s:window", "s:resets", "s:detail"]
        );
        assert!(!format!("{results:?}").contains("\"s:"));
    }
}
//! Token usage and rate limits, normalized across runtimes.

use serde::{Deserialize, Serialize};

use crate::event::redact_opt;

/// Token usage, and its cost where the runtime estimates one.
///
/// Adapters normalize their runtime's reporting into it. Claude, for instance, reports usage
/// per message (repeated across a message's content blocks, and zero in the turn result of an
/// aborted turn), so its adapter sums the messages de-duplicated by message id and takes the
/// final output count from the closing stream delta.
///
/// ## Rules
/// - **Usage comes before `TurnEnded`.** A session emits all of a turn's usage before that
///   turn's [`crate::SessionEvent::TurnEnded`], so the office can close the run's numbers
///   when the turn ends.
/// - **Tokens and cost have separate scopes** ([`token_scope`](Self::token_scope),
///   [`cost_scope`](Self::cost_scope)): a runtime may count tokens per message but cost as a
///   running total (Claude's `total_cost_usd`).
/// - **No running totals that survive the process.** [`UsageScope::Cumulative`] means "since
///   this process started", and the office takes differences. A runtime whose totals run
///   across a resume (Antigravity's per-conversation counts) is converted by its adapter into
///   [`UsageScope::TurnDelta`]s from a baseline:
///   - for a **new conversation** the baseline is 0, so the first turn counts in full;
///   - for a **resume** it's the total the runtime reports when the conversation loads,
///     before any turn. If the runtime reports none then, the adapter can't tell the first
///     turn's share: it takes that turn's total as the baseline, so **the first turn after
///     such a resume isn't counted**, and says so with a [`crate::SessionEvent::Notice`]
///     warning.
///
/// It's `#[non_exhaustive]` so it can grow: build one with [`Usage::new`], then set fields.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[non_exhaustive]
pub struct Usage {
    /// The model the usage is for, where the runtime says.
    pub model: Option<String>,
    /// Input tokens, not counting cache reads.
    pub input: u64,
    /// Output tokens, reasoning included.
    pub output: u64,
    /// Input tokens read from the prompt cache.
    pub cache_read: u64,
    /// Input tokens written to the prompt cache.
    pub cache_write: u64,
    /// Of `output`, the reasoning tokens, where the runtime splits them out.
    pub reasoning: u64,
    /// The cost in US dollars, where the runtime gives one. See
    /// [`cost_basis`](Self::cost_basis).
    pub cost_usd: Option<f64>,
    /// What the cost means.
    pub cost_basis: CostBasis,
    /// Whether the token counts are a delta or a running total since the process started.
    pub token_scope: UsageScope,
    /// Whether the cost is a delta or a running total since the process started.
    pub cost_scope: UsageScope,
}

impl Usage {
    /// No tokens and no cost yet, with these scopes; set the counts after.
    pub fn new(token_scope: UsageScope, cost_scope: UsageScope) -> Self {
        Usage {
            model: None,
            input: 0,
            output: 0,
            cache_read: 0,
            cache_write: 0,
            reasoning: 0,
            cost_usd: None,
            cost_basis: CostBasis::None,
            token_scope,
            cost_scope,
        }
    }

    pub(crate) fn redact(&mut self, f: &mut dyn FnMut(&mut String)) {
        redact_opt(&mut self.model, f);
    }
}

/// What a cost figure means. Unknown values decode as [`CostBasis::Unknown`].
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
#[non_exhaustive]
pub enum CostBasis {
    /// The runtime's estimate at list prices; not what the account is billed.
    ListPriceEstimate,
    /// The runtime gives no cost; the office prices the tokens itself, if at all.
    None,
    /// Not known to this build.
    #[serde(other)]
    Unknown,
}

/// Whether usage numbers are a delta or a running total (see [`Usage`]'s rules). Unknown
/// values decode as [`UsageScope::Unknown`].
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
#[non_exhaustive]
pub enum UsageScope {
    /// Added to what came before: one turn's (or one message's) usage.
    TurnDelta,
    /// The running total since **this process** started: the office takes the difference
    /// from the previous total of the same process. Never a total that survives a resume.
    Cumulative,
    /// Not known to this build.
    #[serde(other)]
    Unknown,
}

/// One rate-limit window's state, as the runtime reports it in-stream or a quota probe reads.
///
/// It's `#[non_exhaustive]` so it can grow: build one with [`RateLimit::new`], then set the
/// optional fields.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[non_exhaustive]
pub struct RateLimit {
    /// Which window.
    pub window: Window,
    /// How much of it is used, from 0.0 to 1.0, where the runtime says.
    pub used_fraction: Option<f64>,
    /// When it resets: RFC 3339 in UTC (e.g. `2026-11-08T05:00:00Z`), converted by the
    /// adapter from whatever the runtime sends.
    pub resets_at: Option<String>,
    /// Whether requests still go through.
    pub status: LimitStatus,
}

impl RateLimit {
    /// A window's state, with no usage fraction or reset time yet.
    pub fn new(window: Window, status: LimitStatus) -> Self {
        RateLimit {
            window,
            used_fraction: None,
            resets_at: None,
            status,
        }
    }

    pub(crate) fn redact(&mut self, f: &mut dyn FnMut(&mut String)) {
        let RateLimit {
            window,
            used_fraction: _,
            resets_at,
            status: _,
        } = self;
        match window {
            Window::Other { id, mins: _ } => f(id),
            Window::FiveHour | Window::SevenDay | Window::Unknown => {}
        }
        redact_opt(resets_at, f);
    }
}

/// A rate-limit window. Unknown kinds decode as [`Window::Unknown`].
#[derive(Debug, Clone, PartialEq, Eq, Hash, Serialize, Deserialize)]
#[serde(tag = "type", rename_all = "snake_case")]
#[non_exhaustive]
pub enum Window {
    /// The rolling five-hour window.
    FiveHour,
    /// The rolling seven-day window.
    SevenDay,
    /// Another window the runtime names.
    Other {
        /// The runtime's name for it.
        id: String,
        /// Its length in minutes, where the runtime says.
        mins: Option<u64>,
    },
    /// Not known to this build.
    #[serde(other)]
    Unknown,
}

/// Whether a rate-limit window still lets requests through. Unknown values decode as
/// [`LimitStatus::Unknown`].
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
#[non_exhaustive]
pub enum LimitStatus {
    /// Fine.
    Ok,
    /// Close to the limit.
    Warning,
    /// Over the limit: requests are refused.
    Rejected,
    /// Not known to this build.
    #[serde(other)]
    Unknown,
}

#[cfg(test)]
mod tests {
    use super::*;
    use serde_json::json;

    #[test]
    fn usage_and_rate_limit_round_trip() {
        let usage = Usage {
            model: None,
            input: 10,
            output: 20,
            cache_read: 30,
            cache_write: 40,
            reasoning: 5,
            cost_usd: None,
            cost_basis: CostBasis::None,
            token_scope: UsageScope::TurnDelta,
            cost_scope: UsageScope::Cumulative,
        };
        let json = serde_json::to_value(&usage).unwrap();
        assert_eq!(json["cost_basis"], json!("none"));
        assert_eq!(json["token_scope"], json!("turn_delta"));
        assert_eq!(json["cost_scope"], json!("cumulative"));
        let mut built = Usage::new(UsageScope::TurnDelta, UsageScope::Cumulative);
        built.input = 10;
        built.output = 20;
        built.cache_read = 30;
        built.cache_write = 40;
        built.reasoning = 5;
        assert_eq!(built, usage);
        assert_eq!(serde_json::from_value::<Usage>(json).unwrap(), usage);

        for window in [
            Window::FiveHour,
            Window::SevenDay,
            Window::Other {
                id: "x".into(),
                mins: None,
            },
        ] {
            let limit = RateLimit {
                window,
                used_fraction: Some(0.9),
                resets_at: None,
                status: LimitStatus::Rejected,
            };
            let json = serde_json::to_string(&limit).unwrap();
            assert_eq!(serde_json::from_str::<RateLimit>(&json).unwrap(), limit);
        }
        assert_eq!(
            serde_json::to_value(Window::FiveHour).unwrap(),
            json!({"type": "five_hour"})
        );
    }

    #[test]
    fn unknown_values_decode_as_unknown() {
        assert_eq!(
            serde_json::from_str::<CostBasis>(r#""billed""#).unwrap(),
            CostBasis::Unknown
        );
        assert_eq!(
            serde_json::from_str::<UsageScope>(r#""per_message""#).unwrap(),
            UsageScope::Unknown
        );
        assert_eq!(
            serde_json::from_str::<LimitStatus>(r#""throttled""#).unwrap(),
            LimitStatus::Unknown
        );
        assert_eq!(
            serde_json::from_value::<Window>(json!({"type": "one_day", "mins": 1440})).unwrap(),
            Window::Unknown
        );
        let limit: RateLimit = serde_json::from_value(json!({
            "window": {"type": "monthly"}, "used_fraction": null, "resets_at": null,
            "status": "soft_blocked"
        }))
        .unwrap();
        assert_eq!(limit.window, Window::Unknown);
        assert_eq!(limit.status, LimitStatus::Unknown);
    }
}
//! The shared JSON-lines framer ([`LineFramer`]) and encoder ([`encode_line`]).
//!
//! Every runtime speaks JSON lines. One framer and one encoder for all of them means line
//! handling can't drift between adapters, and both are pure, so they're tested once here.

use serde::ser::Error as _;
use serde::Serialize;

/// The longest line, without its `\n`, the framer passes on. Longer lines are dropped and
/// reported as [`Frame::Truncated`].
pub const MAX_LINE_BYTES: usize = 4 * 1024 * 1024;

/// One frame out of [`LineFramer`].
///
/// **Exhaustive on purpose**, like [`crate::Output`]: the pump must handle every frame, so a
/// new variant is a breaking change that fails the pump's build until it's handled. Match it
/// without a wildcard arm.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Frame {
    /// A whole line, without its `\n`. It may be empty.
    Line(Vec<u8>),
    /// A line longer than [`MAX_LINE_BYTES`] was dropped. The value is its full length in
    /// bytes, without its `\n`.
    Truncated(usize),
}

/// Splits a byte stream into lines, with bounded memory.
///
/// - It splits on `\n` (byte `0x0A`) **only**. A `\r` before it stays at the end of the line
///   (JSON parsers treat it as whitespace), and U+2028 / U+2029 are ordinary bytes.
/// - It passes lines through as bytes: it doesn't check UTF-8 or JSON.
/// - A line longer than [`MAX_LINE_BYTES`] is dropped while it streams in: its buffer never
///   holds (or reserves) more than `MAX_LINE_BYTES`. When the line ends it's reported **once**, as
///   [`Frame::Truncated`] with the line's full length, and the stream goes on with the next
///   line.
/// - Frames come out in stream order, and are the same however the stream is chunked.
#[derive(Debug, Clone)]
pub struct LineFramer {
    /// The current line so far, while it fits.
    buf: Vec<u8>,
    /// The current line's length so far, once it's too long to keep.
    dropping: Option<usize>,
    cap: usize,
}

impl Default for LineFramer {
    fn default() -> Self {
        Self::new()
    }
}

impl LineFramer {
    /// A framer with the [`MAX_LINE_BYTES`] cap.
    pub fn new() -> Self {
        LineFramer {
            buf: Vec::new(),
            dropping: None,
            cap: MAX_LINE_BYTES,
        }
    }

    /// A framer with a small cap, so tests can exercise truncation on short input.
    #[cfg(test)]
    fn with_cap(cap: usize) -> Self {
        LineFramer { cap, ..Self::new() }
    }

    /// Feeds the next bytes of the stream in, and returns the frames they complete.
    pub fn push(&mut self, mut chunk: &[u8]) -> Vec<Frame> {
        let mut frames = Vec::new();
        while let Some(end) = chunk.iter().position(|&b| b == b'\n') {
            self.extend(&chunk[..end]);
            frames.push(self.take_frame());
            chunk = &chunk[end + 1..];
        }
        self.extend(chunk);
        frames
    }

    /// The stream ended: returns the unterminated last line, if any, and resets the framer.
    ///
    /// The last line comes out as [`Frame::Line`] like any other (a runtime that dies mid-line
    /// leaves a partial line, which then fails to parse); if it was already over the cap it
    /// comes out as [`Frame::Truncated`] with the length seen before the end. `None` if the
    /// stream ended right after a `\n`, or was empty.
    pub fn finish(&mut self) -> Option<Frame> {
        if self.dropping.is_none() && self.buf.is_empty() {
            return None;
        }
        Some(self.take_frame())
    }

    fn extend(&mut self, bytes: &[u8]) {
        if bytes.is_empty() {
            return;
        }
        match &mut self.dropping {
            Some(len) => *len = len.saturating_add(bytes.len()),
            None if self.buf.len() + bytes.len() > self.cap => {
                self.dropping = Some(self.buf.len() + bytes.len());
                // Let go of the memory, not just the contents.
                self.buf = Vec::new();
            }
            None => {
                // Grow geometrically, like `Vec`, but never past the cap, so the buffer's
                // capacity (not just its length) stays within it.
                let needed = self.buf.len() + bytes.len();
                if needed > self.buf.capacity() {
                    let target = needed.max(self.buf.capacity() * 2).min(self.cap);
                    self.buf.reserve_exact(target - self.buf.len());
                }
                self.buf.extend_from_slice(bytes);
            }
        }
    }

    fn take_frame(&mut self) -> Frame {
        match self.dropping.take() {
            Some(len) => Frame::Truncated(len),
            None => Frame::Line(std::mem::take(&mut self.buf)),
        }
    }
}

/// One encoded protocol line, ready to write: compact JSON, U+2028 and U+2029 escaped, no raw
/// line break inside, and exactly one `\n`, at the end.
///
/// **Only [`encode_line`] makes one**, so a session can't build a protocol line by formatting
/// strings (where a `\n` in a person's text would inject a second message). It's what
/// [`crate::Output::Write`] and [`crate::ProbePlan::stdin_lines`] carry.

//! The normalized [`SessionEvent`] stream every runtime maps onto.
//!
//! Events are coarse: no raw runtime JSON rides along. Free text is reachable by
//! [`SessionEvent::redact`], which the office runs before anything is stored or streamed.

use serde::de::{self, Deserializer};
use serde::{Deserialize, Serialize};
use serde_json::Value;

use crate::{RateLimit, SessionId, Usage};

/// What a session reports. Serialized as `{"type": ..., "data": ...}` (`data` left out for
/// [`SessionEvent::Thinking`]); an unknown `type` decodes as [`SessionEvent::Unknown`].
#[derive(Debug, Clone, PartialEq, Serialize)]
#[serde(tag = "type", content = "data", rename_all = "snake_case")]
#[non_exhaustive]
pub enum SessionEvent {
    /// The opening handshake finished; the session takes [`crate::Control`]s now.
    Ready {
        /// The runtime's version, as it reported it.
        runtime_version: Option<String>,
        /// The runtime's pid, if it reported one.
        pid: Option<u32>,
        /// The agents the runtime knows, by name. For a runtime with agents, the session has
        /// already checked that the spec's agent is among them
        /// ([`StartFailure::AgentMismatch`] otherwise); a runtime without agents reports none.
        agents: Vec<String>,
        /// The permission mode the runtime reports it's in, in its own words (e.g. Claude's
        /// `default` for manual). The session has already checked it matches the spec's
        /// ([`StartFailure::ModeMismatch`] otherwise). `None` only for a runtime that never
        /// reports its mode: then nothing could be checked. A runtime that does report one and
        /// leaves it out fails the start as a mismatch (with an empty `reported`).
        permission_mode: Option<String>,
    },
    /// The session couldn't start. [`SessionEvent::Ended`] follows once the process exits.
    StartFailed {
        /// Why.
        reason: StartFailure,
    },
    /// The runtime's id for the conversation, needed to resume it. Emitted once it's known,
    /// even if it was known up front. An id the runtime sends that isn't a valid
    /// [`SessionId`] becomes a [`SessionEvent::ProtocolError`] instead.
    SessionStarted {
        /// The runtime's session (thread, conversation) id.
        runtime_session_id: SessionId,
    },
    /// A turn began.
    TurnStarted {
        /// The runtime's turn id, where it has one (Codex needs it to steer and interrupt).
        turn_id: Option<String>,
        /// `false` for a turn the runtime began on its own (e.g. background work finishing
        /// after a turn ended), not in answer to a send.
        solicited: bool,
    },
    /// The session's activity changed.
    Status(Activity),
    /// Live text as it streams. For display only: never stored.
    TextDelta {
        /// The new text.
        text: String,
    },
    /// A finished piece of the agent's reply.
    AssistantText {
        /// The runtime's message id, where it has one. Several pieces can share one.
        message_id: Option<String>,
        /// The text.
        text: String,
    },
    /// The agent is thinking (reasoning). Coarse on purpose: no text and no token counts,
    /// only that it happened, for a live status.
    Thinking,
    /// The runtime reports its permission mode changed (e.g. after a permission-change
    /// approval), in its own words. `None` if it says the mode changed without naming it.
    ModeChanged {
        /// The new mode, in the runtime's words.
        mode: Option<String>,
    },
    /// The agent began a tool call.
    ToolStarted {
        /// The runtime's id for the call.
        tool_use_id: String,
        /// The tool.
        name: String,
        /// The tool's input, as structured JSON.
        input: Value,
    },
    /// A tool call finished.
    ToolFinished {
        /// The call, as in [`SessionEvent::ToolStarted`].
        tool_use_id: String,
        /// Whether it failed.
        is_error: bool,
    },
    /// The runtime asks whether a tool call may go ahead. Answer with
    /// [`crate::Control::Answer`].
    ApprovalRequested(ApprovalRequest),
    /// The runtime withdrew an approval request (e.g. Claude, on interrupt). Don't answer it.
    ApprovalCancelled {
        /// The withdrawn request.
        id: ApprovalId,
    },
    /// The runtime denied an action without asking (its own policy, or no approval bridge).
    ActionDenied {
        /// The tool.
        tool: String,
        /// The call, where the runtime said which.
        tool_use_id: Option<String>,
        /// The runtime's explanation.
        message: Option<String>,
    },
    /// Token usage and cost.
    Usage(Usage),
    /// A rate-limit window's state.
    RateLimit(RateLimit),
    /// A turn ended.
    TurnEnded {
        /// How it ended.
        outcome: TurnOutcome,
        /// The runtime's error messages for the turn, if any.
        errors: Vec<String>,
    },
    /// Something worth showing that doesn't change the session's state (a retry, a warning).
    Notice {
        /// What kind.
        kind: NoticeKind,
        /// The text.
        text: String,
    },
    /// A line the session couldn't read (invalid JSON, a known message with a bad shape).
    /// The session goes on.
    ProtocolError {
        /// What was wrong. Never the line itself.
        detail: String,
    },
    /// A line too long to read ([`crate::MAX_LINE_BYTES`]) was dropped. The session goes on.
    Truncated {
        /// The dropped line's length in bytes.
        len: usize,
    },
    /// A message type this adapter doesn't know. Its body is dropped. Also what an unknown
    /// event type decodes as.
    Unknown {
        /// The message's type, as the runtime named it.
        type_name: String,
    },
    /// The process exited: the last event of every session, exactly once. Emitted only by
    /// [`crate::Session::on_exit`].
    Ended {
        /// How it exited.
        exit: ExitInfo,
    },
}

/// How a runtime process ended, as the pump saw it when it reaped the process.
