    "action_denied",
    "usage",
    "rate_limit",
    "turn_ended",
    "notice",
    "protocol_error",
    "truncated",
    "unknown",
    "ended",
];

/// The derived decoder for the known event types; [`SessionEvent`]'s own decoder adds the
/// fallback to [`SessionEvent::Unknown`], which serde can't express for a variant with data.
#[derive(Deserialize)]
#[serde(
